Detection.ScriptText:
$keys = @(
    'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\PicPick',
    'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\PicPick'
)
$wanted = [version]'{version}'
foreach ($key in $keys) {
    if (-not (Test-Path -LiteralPath $key)) { continue }
    $entry = Get-ItemProperty -LiteralPath $key -ErrorAction SilentlyContinue
    if (-not $entry) { continue }
    $found = $null
    if (-not [version]::TryParse([string]$entry.DisplayVersion, [ref]$found)) { continue }
    if ($found -ge $wanted) { Write-Output 'Installed'; exit 0 }
}
exit 0
